 "content": "def _runs(row):
    runs = []
    c = 0
    while c < len(row):
        if row[c] == 0:
            c += 1
            continue
        start = c
        while c < len(row) and row[c] != 0:
            c += 1
        runs.append((start, row[start:c]))
    return [seq for _, seq in runs]


def transform(grid):
    """Expand each isolated marker along the row using its boundary template."""
    out = [row[:] for row in grid]
    templates = _runs(grid[0]) + _runs(grid[-1])
    h, w = len(grid), len(grid[0])
    for r in range(1, h - 1):
        for c, color in enumerate(grid[r]):
            if color == 0:
                continue
            matches = [seq for seq in templates if color in seq]
            if not matches:
                continue
            seq = matches[0]
            start = c - seq.index(color)
            for i, value in enumerate(seq):
                cc = start + i
                if 0 <= cc < w:
                    out[r][cc] = value
    return out
